import type { ComboboxLabelProps } from "../combobox.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { ComboboxClasses } from "../combobox.styles";

const ComboboxLabel = forwardRef<HTMLDivElement, ComboboxLabelProps>(
  ({ children, className, ...props }, ref) => {
    return (
      <div ref={ref} className={clsx(ComboboxClasses.groupLabel, className)} {...props}>
        {children}
      </div>
    );
  },
);

ComboboxLabel.displayName = "Combobox.Label";

export { ComboboxLabel };
